import { CORE_RULEBOOK_CHARACTERS } from './core-rulebook-library.js';
const baseAbilities = { Melee:0, Agility:0, Resilience:0, Vigilance:0, Ego:0, Logic:0 };
const LIBRARY_REVISION = 11;
const baseDamage = rank => ({ Melee:Number(rank)||1, Agility:Number(rank)||1, Ego:Number(rank)||1, Logic:Number(rank)||1 });
const clone = value => JSON.parse(JSON.stringify(value));
const session = (id, title, text) => ({ id:String(id).padStart(2,'0'), title, text });

function hero(id,n,r,rank=4,extra={}){
  return {
    id,n,r,rank,tier:'HERÓI',pdf:'',image:'',role:'Herói da campanha',hook:'',
    maxHealth:90,maxFocus:90,currentHealth:90,currentFocus:90,karma:4,healthDR:'—',focusDR:'—',initiative:'+0',
    speed:'Correr 5 · Escalar 3 · Nadar 3 · Pular 3',movement:{run:5,climb:3,swim:3,jump:3},occupation:'',origin:'',teams:'',base:'',
    stats:[['Health',90],['Focus',90],['Karma',4]],abilities:{...baseAbilities},damageMultipliers:baseDamage(rank),traits:[],tags:['Heroic'],powers:[],libraryRevision:LIBRARY_REVISION,
    ...extra
  };
}
function villain(id,n,r='',rank=4,tier='AMEAÇA',extra={}){
  return {
    id,n,r,rank,tier,pdf:'',image:'',role:tier==='CHEFE FINAL'?'VILÃO FINAL':'AMEAÇA',hook:'',
    maxHealth:90,maxFocus:60,currentHealth:90,currentFocus:60,karma:'—',healthDR:'—',focusDR:'—',initiative:'+0',
    speed:'Correr 5 · Escalar 3 · Nadar 3 · Pular 3',movement:{run:5,climb:3,swim:3,jump:3},occupation:'',origin:'',teams:'',base:'',
    abilities:{...baseAbilities},damageMultipliers:baseDamage(rank),traits:[],tags:['Villainous'],powers:[],libraryRevision:LIBRARY_REVISION,
    ...extra
  };
}

function minion(id,n,rank=1,{description='',health=10,defense=10,speed=6,melee=0,agility=0,resilience=0,vigilance=0,plannedImage='',attacks=[],skills=[]}={}){
  return villain(id,n,'',rank,'CAPANGA',{
    generic:true,
    image:plannedImage,
    role:'Capanga / ameaça',
    hook:description,
    maxHealth:health,maxFocus:0,currentHealth:health,currentFocus:0,
    defense,
    initiative:'+0',
    speed:'Correr '+speed,
    movement:{run:speed,climb:Math.min(3,speed),swim:3,jump:3},
    abilities:{Melee:melee,Agility:agility,Resilience:resilience,Vigilance:vigilance,Ego:0,Logic:0},
    attacks:[...attacks],
    specialAbilities:[...skills],
    plannedImage,
    traits:skills.map(item=>String(item).split(':')[0]),
    tags:['Villainous','Capanga','Defesa '+defense],
    powers:[...attacks.map(item=>'Ataque — '+item),...skills.map(item=>'Habilidade — '+item)]
  });
}


