function inferDamageProfile(character){
  const profile=baseDamage(character?.rank||1);
  for(const power of character?.powers||[]){
    const text=String(power||'');
    const mighty=text.match(/(?:Mighty|Poderoso)\s*(\d+)/i);if(mighty)profile.Melee+=Number(mighty[1]||0);
    const accuracy=text.match(/(?:Accuracy|Precisão)\s*(\d+)/i);if(accuracy)profile.Agility+=Number(accuracy[1]||0);
    const brilliance=text.match(/(?:Brilliance|Brilhantismo)\s*(\d+)/i);if(brilliance)profile.Logic+=Number(brilliance[1]||0);
  }
  return profile;
}
for(const bucket of [CHARACTER_LIBRARY.heroes,CHARACTER_LIBRARY.villains]){
  for(const character of Object.values(bucket))character.damageMultipliers=inferDamageProfile(character);
}

