function characterList(kind){
  if(kind==='hero') return Object.values(CHARACTER_LIBRARY.heroes).map(clone);
  if(kind==='villain') return Object.values(CHARACTER_LIBRARY.villains).map(clone);
  return { heroes: characterList('hero'), villains: characterList('villain') };
}
function getChar(kind,id){
  const primary = kind==='hero' ? CHARACTER_LIBRARY.heroes : CHARACTER_LIBRARY.villains;
  const secondary = kind==='hero' ? CHARACTER_LIBRARY.villains : CHARACTER_LIBRARY.heroes;
  const sourceKind = primary[id] ? kind : secondary[id] ? (kind==='hero'?'villain':'hero') : null;
  const source = primary[id] || secondary[id];
  if(!source)return null;
  const item=clone(source);
  item.libraryKind=sourceKind;
  item.rosterKind=kind;
  if(sourceKind!==kind){
    if(item.type==='minion')item.tier='LACAIO';
    else if(item.alignment==='antihero')item.tier='ANTI-HERÓI';
    else if(item.alignment==='wildcard')item.tier='WILDCARD';
    else item.tier=kind==='hero'?'HERÓI':'AMEAÇA';
  }
  return item;
}
function buildScenarioPieces(heroes){
  return heroes.slice(0,6).map((h,i)=>({id:`hero-${h.id}`,kind:'hero',baseId:h.id,name:h.n,image:h.image||'',short:h.n.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),color:['#ef4444','#facc15','#3b82f6','#22c55e','#a855f7','#06b6d4'][i%6],x:2+i*2,y:12,movement:h.movement||{run:5,climb:3,swim:3,jump:3}}));
}
function buildTemplate({id,name,subtitle,rank,players,finalVillain,accent,summary,mode='group',source='uploaded-campaign',campaignPdf='',heroIds=[],villainIds=[],sessions=[]}){
  return { id,name,subtitle,rank,players,finalVillain,accent,summary,mode,source,campaignPdf, heroes: heroIds.map(heroId=>getChar('hero',heroId)).filter(Boolean), villains: villainIds.map(villainId=>getChar('villain',villainId)).filter(Boolean), sessions };
}

