function rosterSummary(items, kind='hero'){
  return items.map(item => kind==='hero'
    ? { id:item.id,n:item.n,r:item.r,rank:item.rank,image:item.image||'',pdf:!!item.pdf,role:item.role||'',powers:item.powers||[],abilities:item.abilities||baseAbilities }
    : { id:item.id,n:item.n,r:item.r,rank:item.rank,tier:item.tier,image:item.image||'',pdf:!!item.pdf,role:item.role||'',powers:item.powers||[],abilities:item.abilities||baseAbilities }
  );
}

